+            TypeBindings tb = null;
+            if (baseType.containedTypeCount() == typeParamCount) {
+                if (typeParamCount == 1) {
+                    tb = TypeBindings.create(subclass, baseType.containedType(0));
+                } else if (typeParamCount == 2) {
+                    tb = TypeBindings.create(subclass, baseType.containedType(0),
